import{_ as t,a0 as r,w as o,s as d,I as e,x as a,a1 as i,A as l,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"如何在CentOS中創建輔域名服務器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在CentOS中創建輔域名服務器 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在CentOS中創建輔域名服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在CentOS中創建輔域名服務器 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/How to set up a secondary DNS server in CentOS","title":"如何在CentOS中創建輔域名服務器","tag":"201405","desc":""},"relativePath":"201405/How to set up a secondary DNS server in CentOS.md","filePath":"[post].md"}'),h={name:"201405/How to set up a secondary DNS server in CentOS.md"};function c(g,s,k,u,b,m){const n=r("Link");return o(),d("div",null,[s[17]||(s[17]=e("h1",{id:"如何在centos中創建輔域名服務器",tabindex:"-1"},[a("如何在CentOS中創建輔域名服務器 "),e("a",{class:"header-anchor",href:"#如何在centos中創建輔域名服務器","aria-label":"Permalink to “如何在CentOS中創建輔域名服務器”"},"​")],-1)),e("p",null,[s[1]||(s[1]=a("在",-1)),i(n,{href:"http://linux.cn/article-3092-1.html"},{default:l(()=>[...s[0]||(s[0]=[a("上篇教程",-1)])]),_:1}),s[2]||(s[2]=a("裏，我們為一個測試域exmample.tst創建了一個主域名服務器（ns1）。在本篇中，我們會在CentOS中使用bind包為相同的域創建一個輔域名服務器（ns2）。",-1))]),s[18]||(s[18]=p('<p>當創建一個輔DNS服務器的時候，下面的因素需要仔細考慮。</p><ul><li>在輔域名服務器中，你不需要手動創建正向和反向區域文件。這些區域文件會定期從主域名服務器上面同步。</li><li>當主域名服務器上的任何區域文件被修改的時候，&#39;serial&#39;參數也應當被更新。只有當主服務器上面區域文件的serial被修改之後，輔DNS服務器才會進行同步。</li></ul><p>我們假設輔DNS服務器的IP地址是172.16.1.4。讓我們來進行安裝。</p><h3 id="設置主機名" tabindex="-1">設置主機名 <a class="header-anchor" href="#設置主機名" aria-label="Permalink to “設置主機名”">​</a></h3><p>就像主域名服務器一樣，輔域名服務器的主機名也應當是一個完全限定域名（FQDN）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vim /etc/sysconfig/network</span></span></code></pre></div><blockquote><p>HOSTNAME=ns2.example.tst</p></blockquote><p>注意，在該文件中設置的主機名在服務器啓動的時候會被使用。因此，如果你在系統啓動之後修改該文件，修改結果不會立刻生效。下面的命令可以用來在系統運行的時候修改並及時生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># hostname ns2.example.tst</span></span></code></pre></div><p>設置之後，可以用下面的命令來查看主機名稱。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># hostname</span></span></code></pre></div><hr><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ns2.example.tst</span></span></code></pre></div><p>在進行下面的步驟之前，確保所有三台服務器的主機名稱已經被正確設置。</p><h3 id="安裝軟件包" tabindex="-1">安裝軟件包 <a class="header-anchor" href="#安裝軟件包" aria-label="Permalink to “安裝軟件包”">​</a></h3>',15)),e("p",null,[s[4]||(s[4]=a("就像",-1)),i(n,{href:"http://linux.cn/article-3092-1.html"},{default:l(()=>[...s[3]||(s[3]=[a("主服務器",-1)])]),_:1}),s[5]||(s[5]=a("一樣，配置一台輔域名服務器可以使用chroot或者不用。必須的軟件包可以使用yum輕鬆安裝。",-1))]),s[19]||(s[19]=p(`<p>不使用 chroot:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install bind</span></span></code></pre></div><p>使用 chroot:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install bind-chroot</span></span></code></pre></div><h3 id="為區域文件的傳輸準備配置文件" tabindex="-1">為區域文件的傳輸準備配置文件 <a class="header-anchor" href="#為區域文件的傳輸準備配置文件" aria-label="Permalink to “為區域文件的傳輸準備配置文件”">​</a></h3><p>在CentOS中使用bind創建域名服務器後，默認設置允許所有的區域文件被任意服務器同步。安全起見，我們需要配置主域名服務器，只允許它允許輔域名服務器進行同步。</p><h4 id="_1-主域名服務器" tabindex="-1">1. 主域名服務器 <a class="header-anchor" href="#_1-主域名服務器" aria-label="Permalink to “1. 主域名服務器”">​</a></h4><p>不使用chroot：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    # vim /etc/named.conf</span></span></code></pre></div><p>使用chroot：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    # vim /var/named/chroot/etc/named.conf</span></span></code></pre></div><hr><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>zone &quot;example.tst&quot; IN {</span></span>
<span class="line"><span>    type master;</span></span>
<span class="line"><span>    file &quot;example-fz&quot;; ## 文件example-fz在主域名服務器上 ##</span></span>
<span class="line"><span>    allow-update { none; };</span></span>
<span class="line"><span>    allow-transfer {172.16.1.4; }; ## 允許輔域名服務器進行傳輸 ##</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>zone &quot;1.16.172.in-addr.arpa&quot; IN {</span></span>
<span class="line"><span>    type master;</span></span>
<span class="line"><span>    file &quot;rz-172-16-1&quot;; ##文件rz-172-16-1在主域名服務器上##</span></span>
<span class="line"><span>    allow-update { none; };</span></span>
<span class="line"><span>    allow-transfer {172.16.1.4; }; ## 允許輔域名服務器進行傳輸 ##</span></span>
<span class="line"><span>};</span></span></code></pre></div><h4 id="_2-輔域名服務器" tabindex="-1">2. 輔域名服務器 <a class="header-anchor" href="#_2-輔域名服務器" aria-label="Permalink to “2. 輔域名服務器”">​</a></h4><p>軟件安裝後提供的默認配置文件就可以用來配置輔域名服務器。但是，我們使用會使用另外一個實例配置文件來進行配置，因為這樣便於調整。</p><p>不使用chroot：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cp /usr/share/doc/bind-9.8.2/sample/etc/named.rfc1912.zones /etc/named.conf</span></span></code></pre></div><p>使用chroot：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cp /usr/share/doc/bind-9.8.2/sample/etc/named.rfc1912.zones /var/named/chroot/etc/named.conf</span></span></code></pre></div><p>當執行完上面的命令進行文件拷貝後，添加下面的內容到剛才那個拷貝後的文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>options {</span></span>
<span class="line"><span>        directory &quot;/var/named&quot;;</span></span>
<span class="line"><span>        forwarders {8.8.8.8; };</span></span>
<span class="line"><span></span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>zone &quot;example.tst&quot; IN {</span></span>
<span class="line"><span>        type slave;  ## 該主機為輔域名服務器 ##</span></span>
<span class="line"><span>        file &quot;example-fz&quot;; ## 這個文件會被自動創建 ##</span></span>
<span class="line"><span>        //allow-update { none; };</span></span>
<span class="line"><span>        allow-transfer {172.16.1.3; };  ## 定義必要時進行從其傳輸的主域名服務器 ##</span></span>
<span class="line"><span>        masters {172.16.1.3; }; ## 定義主域名服務器 ##</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>zone &quot;1.16.172.in-addr.arpa&quot; IN {</span></span>
<span class="line"><span>        type slave; ## 該主機被定義為輔域名服務器 ##</span></span>
<span class="line"><span>        file &quot;rz-172-16-1&quot;; ## 這個文件會被自動創建 ##</span></span>
<span class="line"><span>//      allow-update { none; };</span></span>
<span class="line"><span>        allow-transfer {172.16.1.3; };  ## 定義主域名服務器 ##</span></span>
<span class="line"><span>        masters {172.16.1.3; };</span></span>
<span class="line"><span>};</span></span></code></pre></div><h3 id="結束工作" tabindex="-1">結束工作 <a class="header-anchor" href="#結束工作" aria-label="Permalink to “結束工作”">​</a></h3><p>為了確保沒有權限相關的問題，我們需要做如下調整。</p><p>不使用chroot：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chmod 770 /var/named/</span></span></code></pre></div><p>使用chroot，你需在named服務啓動後按照下面的命令修改權限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># chmod 770 /var/named/chroot/var/named</span></span></code></pre></div><p>現在萬事俱備，我們可以重啓named服務。或者，確保named服務已經被加到了開始列表中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># service named restart</span></span>
<span class="line"><span># chkconfig named on</span></span></code></pre></div><p>如果不出意外，輔域名服務器應該會向主域名服務器請求一個區域的傳輸，並且產生自己的/var/named目錄。日誌文件/var/log/messages會包含一些named服務的有用信息，包括區域文件傳輸過程中的信息。</p><h3 id="測試一個輔域名服務器" tabindex="-1">測試一個輔域名服務器 <a class="header-anchor" href="#測試一個輔域名服務器" aria-label="Permalink to “測試一個輔域名服務器”">​</a></h3><p>我們可以使用dig或者nslookup進行DNS測試操作。在本篇教程中我們會使用nslookup來進行演示。必要的軟件包可以通過yum進行安裝。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install bind-utils</span></span>
<span class="line"><span># nslookup</span></span></code></pre></div><hr><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; server 172.16.1.4</span></span>
<span class="line"><span>Default server:     172.16.1.4</span></span>
<span class="line"><span>Address:            172.16.1.4#53</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; example.tst</span></span>
<span class="line"><span>Server:             172.16.1.4</span></span>
<span class="line"><span>Address:    172.16.1.4#53</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Name:       example.tst</span></span>
<span class="line"><span>Address:    172.16.1.3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; set type=mx</span></span>
<span class="line"><span>&gt; example.tst</span></span>
<span class="line"><span>Server:             172.16.1.4</span></span>
<span class="line"><span>Address:            172.16.1.4#53</span></span>
<span class="line"><span></span></span>
<span class="line"><span>example.tst         mail exchanger = 10 mail.example.tst.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; exit</span></span></code></pre></div><h3 id="排錯提示" tabindex="-1">排錯提示 <a class="header-anchor" href="#排錯提示" aria-label="Permalink to “排錯提示”">​</a></h3><ol><li><p>我們無需在輔域名服務器上創建任何區域文件。所有的區域文件都會與主域名服務器進行同步。</p></li><li><p>輔域名服務器上的named服務會定期與主服務器進行同步。如果你想來一次及時的同步，可以使用命令 <code>rncd retransfer &lt;FQDN&gt;</code>。如下：</p></li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># rndc retransfer example.tst</span></span></code></pre></div><ol start="3"><li><p>只有當主服務器上區域文件的serial數字被修改變大的時候，輔域名服務器才會進行更新。</p></li><li><p>確保用户named可以對文件夾/var/named或者/var/named/chroot/var/named（使用chroot的情況下）進行寫操作。</p></li><li><p>/var/log/messages會包含有用的信息。</p></li><li><p>我已經將SELinux關閉了。</p></li><li><p>確保防火牆對UDP53端口開放。</p></li></ol><p>希望這個可以幫到你。</p><hr>`,41)),e("p",null,[s[7]||(s[7]=a("via: ",-1)),i(n,{href:"http://xmodulo.com/2014/04/secondary-dns-server-centos.html"},{default:l(()=>[...s[6]||(s[6]=[a("http://xmodulo.com/2014/04/secondary-dns-server-centos.html",-1)])]),_:1})]),e("p",null,[s[10]||(s[10]=a("譯者：",-1)),i(n,{href:"https://github.com/zzlyzq"},{default:l(()=>[...s[8]||(s[8]=[a("zzlyzq",-1)])]),_:1}),s[11]||(s[11]=a(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:l(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[14]||(s[14]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[12]||(s[12]=[a("LCTT",-1)])]),_:1}),s[15]||(s[15]=a(" 原創翻譯，",-1)),i(n,{href:"http://linux.cn/"},{default:l(()=>[...s[13]||(s[13]=[a("Linux中國",-1)])]),_:1}),s[16]||(s[16]=a(" 榮譽推出",-1))])])}const C=t(h,[["render",c]]);export{v as __pageData,C as default};
